        List<OrderResponse.ItemResponse> items = new ArrayList<>();
        for (OrderItem item : order.getItems()) {
            items.add(new OrderResponse.ItemResponse(item.getSku(), item.getQuantity()));
        }
        response.setItems(items);

        return response;
    }
}

