        Mockito.when(transLogService.getQuote(anyString(), any(), anyString()))
                .thenReturn(TransLogService.QuoteResult.success(new BigDecimal("50.80"), 3));

        CheckoutRequest request = createRequest(
                "12345678909", "ana@exemplo.com",
                List.of(
                        item("JAQ-001", 3),
